// Generated by etl/99_stamp_sw.mjs for production builds.
const CACHE_LAYERS = {"shell":{"name":"pyfa:app:dev","urls":["/","/index.html","/manifest.webmanifest"]},"icons":{"name":"pyfa-icons-dev","urls":[]},"runtime":null,"data":[]}
const { shell, icons, runtime, data } = CACHE_LAYERS
const layers = [icons, shell, runtime, ...data].filter(Boolean)
const current = new Set(layers.map(({ name }) => name))
const dataByPath = new Map(data.flatMap(({ name, urls }) => urls.map((url) => [url, name])))
const legacyName = /^pyfa-(?!icons-).+-[a-f0-9]{64}$/

async function precache({ name, urls }, legacy) {
  const cache = await caches.open(name)
  const missing = []
  for (const url of urls) {
    if (await cache.match(url)) continue
    // Earlier versions already cached these immutable URLs in one build-wide cache.
    const reusable = (name === runtime?.name || /^pyfa:data:[a-f0-9]{64}$/.test(name))
      ? await legacy?.match(url) : undefined
    if (reusable) await cache.put(url, reusable)
    else missing.push(url)
  }
  if (missing.length) await cache.addAll(missing)
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const previous = await caches.keys()
    const oldName = previous.find((name) => legacyName.test(name))
    const legacy = oldName ? await caches.open(oldName) : undefined
    const results = await Promise.allSettled(layers.map((layer) => precache(layer, legacy)))
    const failed = results.find((result) => result.status === 'rejected')
    if (failed) {
      await Promise.all(layers.filter(({ name }) => !previous.includes(name)).map(({ name }) => caches.delete(name)))
      throw failed.reason
    }
    await self.skipWaiting()
  })())
})

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys()
    await Promise.all(keys.filter((name) => (name.startsWith('pyfa-') || name.startsWith('pyfa:')) && !current.has(name)).map((name) => caches.delete(name)))
    await self.clients.claim()
  })())
})

async function cachedAsset(request, name, markSource) {
  const cache = await caches.open(name)
  const cached = await cache.match(request)
  if (cached) {
    if (!markSource) return cached
    const headers = new Headers(cached.headers)
    headers.set('X-Pyfa-Source', 'cache')
    return new Response(cached.body, { status: cached.status, statusText: cached.statusText, headers })
  }
  const response = await fetch(request)
  if (response.ok && response.status === 200) {
    await cache.put(request, response.clone()).catch(() => {})
  }
  return response
}

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET' || request.headers.has('range')) return
  const url = new URL(request.url)
  if (url.origin !== location.origin) return
  const { pathname } = url

  if (request.mode === 'navigate') {
    event.respondWith(caches.open(shell.name).then(async (cache) =>
      (await cache.match('/index.html')) ?? fetch(request)))
    return
  }

  const dataCache = dataByPath.get(pathname)
  if (dataCache) {
    event.respondWith(cachedAsset(request, dataCache, pathname !== '/data/manifest.json'))
  } else if (runtime?.urls.includes(pathname)) {
    // Keep executable responses intact for the browser's script and WebAssembly caches.
    event.respondWith(cachedAsset(request, runtime.name, !/\.(?:m?js|wasm)$/.test(pathname)))
  } else if (pathname.startsWith('/img/') || icons.urls.includes(pathname)) {
    event.respondWith(cachedAsset(request, icons.name, false))
  } else if (shell.urls.includes(pathname)) {
    event.respondWith(cachedAsset(request, shell.name, false))
  }
})
